def transform(grid):
    """Draw a full-width color-3 line across the empty row separating the two figures."""
    out = [row[:] for row in grid]
    h = len(grid)
    # Find a completely empty row with non-empty content on both sides.
    for r in range(h):
        if all(v == 0 for v in grid[r]) and any(any(v != 0 for v in row) for row in grid[:r]) and any(any(v != 0 for v in row) for row in grid[r + 1:]):
            out[r] = [3] * len(grid[r])
            break
    return out
